{
  "findings": [
    {
      "check_id": "CKV_AWS_5",
      "title": "Ensure all data stored in the Elasticsearch is securely encrypted at rest",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "HIGH",
      "explanation": "The `encrypt_at_rest` block explicitly sets `enabled = false`, leaving sensitive log data unencrypted on disk, which violates security best practices and compliance requirements."
    },
    {
      "check_id": "CKV_AWS_6",
      "title": "Ensure all Elasticsearch has node-to-node encryption enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "Node-to-node encryption is not configured (missing `node_to_node_encryption` block), meaning traffic between nodes within the cluster is transmitted in plaintext, exposing it to potential interception within the VPC."
    },
    {
      "check_id": "CKV_AWS_84",
      "title": "Ensure Elasticsearch Domain Logging is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "Logging configuration (`log_publishing_options`) is missing, preventing visibility into index slow logs, search slow logs, and application errors, which hinders security monitoring and troubleshooting."
    },
    {
      "check_id": "CKV2_AWS_59",
      "title": "Ensure ElasticSearch/OpenSearch has dedicated master node enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The cluster configuration lacks dedicated master nodes (`dedicated_master_enabled` is not set or false). With only 2 data nodes, this increases the risk of cluster instability and split-brain scenarios during high load or node failures."
    }
  ],
  "patched_code": "resource "aws_elasticsearch_domain" "log_search_database" {
  domain_name           = "enterprise-log-analytics-es"
  elasticsearch_version = "7.10"
  cluster_config {
    instance_type              = var.elasticsearch_instance_type
    instance_count             = 3
    dedicated_master_enabled   = true
    dedicated_master_count     = 3
    dedicated_master_type      = "m5.large.elasticsearch"
  }
  vpc_options {
    subnet_ids         = [aws_subnet.data_subnet_az1.id]
    security_group_ids = [aws_security_group.elasticsearch_sg.id]
  }
  ebs_options {
    ebs_enabled = true
    volume_size = 20
    volume_type = "gp2"
  }
  encrypt_at_rest {
    enabled = true
  }
  node_to_node_encryption {
    enabled = true
  }
  log_publishing_options {
    log_type                 = "INDEX_SLOW_LOGS"
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.es_logs.arn
  }
}

resource "aws_cloudwatch_log_group" "es_logs" {
  name              = "/aws/es/enterprise-log-analytics-es"
  retention_in_days = 30
}",
  "fix_summary": "Enabled encryption at rest and node-to-node encryption. Added dedicated master nodes for high availability and stability. Configured CloudWatch logging for index slow logs by adding a log group resource and publishing options."
}
